using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long u, v;
    cin >> n >> u >> v;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    // Compress values; a target missing from the array can never be in a window.
    vector<long long> uniq(a);
    sort(uniq.begin(), uniq.end());
    uniq.erase(unique(uniq.begin(), uniq.end()), uniq.end());
    auto find = [&](long long x) {
        auto it = lower_bound(uniq.begin(), uniq.end(), x);
        return it != uniq.end() && *it == x ? int(it - uniq.begin()) : -1;
    };
    int iu = find(u), iv = find(v);
    if (iu < 0 || iv < 0) {
        cout << 0 << '\n';
        return 0;
    }
    vector<int> id(n), freq(uniq.size(), 0);
    for (int i = 0; i < n; i++) id[i] = lower_bound(uniq.begin(), uniq.end(), a[i]) - uniq.begin();
    int left = 0, distinct = 0, answer = n + 1;
    for (int r = 0; r < n; r++) {
        if (freq[id[r]]++ == 0) distinct++;
        // Shrink while the window still holds both targets.
