import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long u = nextLong(), v = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Compress values; a target missing from the array can never be in a window.
        long[] uniq = a.clone();
        Arrays.sort(uniq);
        int k = 0;
        for (int i = 0; i < n; i++) if (i == 0 || uniq[i] != uniq[i - 1]) uniq[k++] = uniq[i];
        int iu = Arrays.binarySearch(uniq, 0, k, u), iv = Arrays.binarySearch(uniq, 0, k, v);
        if (iu < 0 || iv < 0) {
            System.out.println(0);
            return;
        }
        int[] id = new int[n], freq = new int[k];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(uniq, 0, k, a[i]);
        int left = 0, distinct = 0, answer = n + 1;
        for (int r = 0; r < n; r++) {
            if (freq[id[r]]++ == 0) distinct++;
            // Shrink while the window still holds both targets.
            while (freq[iu] > 0 && freq[iv] > 0) {
                answer = Math.min(answer, distinct);
                if (--freq[id[left++]] == 0) distinct--;
            }
        }
        System.out.println(answer <= n ? answer : 0);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	u, v := nextInt(), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Compress values; a target missing from the array can never be in a window.
	uniq := slices.Clone(a)
	slices.Sort(uniq)
	uniq = slices.Compact(uniq)
	iu, okU := slices.BinarySearch(uniq, u)
	iv, okV := slices.BinarySearch(uniq, v)
	if !okU || !okV {
		fmt.Println(0)
		return
	}
	id := make([]int, n)
	for i, x := range a {
		id[i], _ = slices.BinarySearch(uniq, x)
	}
	freq := make([]int, len(uniq))
	left, distinct, answer := 0, 0, n+1
	for r := 0; r < n; r++ {
		if freq[id[r]] == 0 {
			distinct++
		}
		freq[id[r]]++
		// Shrink while the window still holds both targets.
		for freq[iu] > 0 && freq[iv] > 0 {
			answer = min(answer, distinct)
			freq[id[left]]--
			if freq[id[left]] == 0 {
				distinct--
			}
			left++
		}
	}
	if answer > n {
		answer = 0
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
